189	static int create_bt_folder(void)
190	{
191	    int ret = 0;
192	
193	    if (mkdir(MISC_PATH, 0777) == -1 && errno != EEXIST) {
194	        ret = -1;
195	        syslog(LOG_ERR, MISC_PATH " folder create fail, errno: %d\n", errno);
196	        goto out;
197	    }
198	
199	    if (mkdir(BT_FOLDER_PATH, 0777) == -1 && errno != EEXIST) {
200	        ret = -1;
201	        syslog(LOG_ERR, BT_FOLDER_PATH " folder create fail, errno: %d\n", errno);
202	        goto out;
203	    }
204	
205	out:
206	    syslog(LOG_INFO, BT_FOLDER_PATH " folder create: %d\n", ret);
207	    return ret;
208	}
