326	static int h4_open(const struct device* dev, bt_hci_recv_t recv, void* hci_data)
327	{
328	    int fd;
329	    struct h4_data* h4;
330	
331	    fd = open(CONFIG_BT_UART_ON_DEV_NAME, O_RDWR | O_BINARY | O_CLOEXEC);
332	    if (fd < 0) {
333	        BT_LOGE("H4: Failed to open %s: %d", CONFIG_BT_UART_ON_DEV_NAME, errno);
334	        return fd;
335	    }
336	
337	    h4 = dev->data;
338	    h4->fd = fd;
339	    h4->recv = recv;
