343	    BT_LOGE("H4: %s opened as fd:%d", CONFIG_BT_UART_ON_DEV_NAME, h4->fd);
344	
345	    hci_handle = service_loop_poll_fd(h4->fd, POLL_READABLE, hci_poll_recv, NULL);
346	    if (!hci_handle) {
347	        BT_LOGD("hci fd:%d add poll failed", h4->fd);
348	        return -1;
349	    }
350	
351	    return 0;
352	}
