1	/****************************************************************************
2	 * app/bt_test/bt_test.c
3	 *
4	 * Simple BT test: open /dev/ttyHCI0 to trigger BT stack init and LCPU boot.
5	 ****************************************************************************/
6	
7	#include <nuttx/config.h>
8	#include <stdio.h>
9	#include <fcntl.h>
10	#include <unistd.h>
11	#include <errno.h>
12	
13	int main(int argc, char *argv[])
14	{
15	  int fd;
16	  uint8_t hci_reset[] = {0x01, 0x03, 0x0c, 0x00}; /* HCI Reset */
17	  ssize_t n;
18	  uint8_t buf[256];
19	
20	  printf("BT Test: opening /dev/ttyHCI0...\n");
21	
22	  fd = open("/dev/ttyHCI0", O_RDWR);
23	  if (fd < 0)
24	    {
25	      printf("open failed: %d\n", errno);
26	      return -1;
27	    }
28	
29	  printf("BT Test: sending HCI Reset...\n");
30	
31	  n = write(fd, hci_reset, sizeof(hci_reset));
32	  if (n < 0)
33	    {
34	      printf("write failed: %d\n", errno);
35	      close(fd);
36	      return -1;
37	    }
38	
39	  printf("BT Test: sent %zd bytes, waiting for response...\n", n);
40	
41	  usleep(500000); /* 500ms */
42	
43	  n = read(fd, buf, sizeof(buf));
44	  if (n < 0)
45	    {
46	      printf("read failed: %d\n", errno);
47	    }
48	  else
49	    {
50	      printf("BT Test: received %zd bytes:", n);
51	      for (int i = 0; i < n && i < 32; i++)
52	        {
53	          printf(" %02x", buf[i]);
54	        }
55	      printf("\n");
56	    }
57	
58	  close(fd);
59	  printf("BT Test: done\n");
60	  return 0;
61	}
